// The encoder captures a refined type by its basetype, so a refinement must record the same bytes
// as the primitive kind it refines.
static_assert(std::is_same_v<format::EncodeTypeFor<format::kind::DeviceAddress>, format::EncodeTypeFor<format::kind::UInt64>>);
static_assert(std::is_same_v<format::EncodeTypeFor<format::kind::DeviceSize>, format::EncodeTypeFor<format::kind::UInt64>>);
static_assert(std::is_same_v<format::EncodeTypeFor<format::kind::SampleMask>, format::EncodeTypeFor<format::kind::UInt32>>);

